import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner s = new Scanner(System.in);
        int capacity = s.nextInt(), n = s.nextInt();
        Deque<String> q = new ArrayDeque<>();
        for (int i = 0; i < n; i++) {
            String op = s.next();
            if (op.equals("add")) {
                String v = s.next();
                if (q.size() >= capacity) System.out.println("rejected " + v);
                else q.addLast(v);
            } else {
                String v = q.pollFirst();
                System.out.println(v == null ? "empty" : v);
            }
        }
        System.out.println("queue=" + q);
    }
}
